// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(address receiver, uint256 amount) public {
        // admissible domain: any non-zero receiver other than c itself, any spendable amount > 0
        vm.assume(receiver != address(0));
        vm.assume(receiver != address(c));
        vm.assume(receiver != address(this));
        amount = bound(amount, 1, address(this).balance);

        // owner of c is the test contract (deployer); fund c with exactly `amount`
        vm.deal(address(c), amount);
        uint256 receiverBefore = address(receiver).balance;
        uint256 cBefore = address(c).balance;

        vm.prank(address(this));
        bool ok;
        try c.sendTo(receiver, amount) { ok = true; } catch { ok = false; }

        // GENERAL RULE: when the call succeeds, `amount` wei must reach the requested
        // receiver and be debited from c. The mutant always pays `owner` instead, so
        // the receiver's balance never increases (delta == 0) while ok == true.
        assertTrue(ok && address(receiver).balance == receiverBefore + amount && address(c).balance == cBefore - amount);
    }
}
